CREATE TABLE IF NOT EXISTS direccion_guardada(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,etiqueta VARCHAR(40) NOT NULL,nombre VARCHAR(120) NOT NULL,email VARCHAR(120) NOT NULL,run VARCHAR(15) NOT NULL,telefono VARCHAR(16) NOT NULL,region VARCHAR(120) NOT NULL,comuna VARCHAR(120) NOT NULL,direccion VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS direccion_bloqueo(usuario_id BIGINT PRIMARY KEY);
